// ServiceOption configures [AssertServiceContract].
type ServiceOption func(*serviceConfig)

// ServicePrePopulate runs before subtests that need pre-populated state.
// Called once per subtest against a fresh impl from the factory.
func ServicePrePopulate(fn func(ctx context.Context, s multireturns.Service)) ServiceOption {
	return func(c *serviceConfig) { c.prePopulate = fn }
}

// ServiceCustom adds a free-form subtest to the contract. Use this for
// contracts not expressible via shape-specific primitives.
func ServiceCustom(name string, fn func(*testing.T, multireturns.Service)) ServiceOption {
	return func(c *serviceConfig) {
		c.custom = append(c.custom, serviceCustomSubtest{name: name, fn: fn})
	}
}

// ServiceOnCheckout adds plug-in assertions for the Checkout method.
func ServiceOnCheckout(assertions ...func(*testing.T, multireturns.Service)) ServiceOption {
	return func(c *serviceConfig) {
		c.onCheckout = append(c.onCheckout, assertions...)
	}
}

// ServiceOnPeek adds plug-in assertions for the Peek method.
